    seen = set()
    border_components = []
    for r,c in ((r,c) for r in range(h) for c in range(w) if grid[r][c] == 1):
        if (r,c) in seen:
            continue
        comp = {(r,c)}
        seen.add((r,c)); q = deque([(r,c)])
        while q:
            x,y = q.popleft()
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    nx,ny=x+dx,y+dy
                    if (dx or dy) and 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and (nx,ny) not in seen:
                        seen.add((nx,ny)); comp.add((nx,ny)); q.append((nx,ny))
