            out[r][c] = 3
    for r,c in wall:
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) in outside:
                out[nr][nc]=2
    return out
